namespace AgentsApp.Shared.Features.Announcements.Dtos;

[DtoResourceType(typeof(AppStrings))]
public partial class AnnouncementDto
{
    public Guid Id { get; set; }

    [Required(ErrorMessage = nameof(AppStrings.RequiredAttribute_ValidationError))]
    [Display(Name = nameof(AppStrings.Title))]
    [MaxLength(120, ErrorMessage = nameof(AppStrings.MaxLengthAttribute_InvalidMaxLength))]
    public string? Title { get; set; }

    [Required(ErrorMessage = nameof(AppStrings.RequiredAttribute_ValidationError))]
    [Display(Name = nameof(AppStrings.Description))]
    [MaxLength(1000, ErrorMessage = nameof(AppStrings.MaxLengthAttribute_InvalidMaxLength))]
    public string? Body { get; set; }

    public DateTimeOffset PublishedOn { get; set; }

    public DateTimeOffset? ExpiresOn { get; set; }

    public long Version { get; set; }
}

