@inherits AppComponentBase

<section>
    <BitStack Gap="0.5rem">
        <BitText Typography="BitTypography.H6" Style="color:#1565c0">@Localizer["Quick note"]</BitText>
        <BitTextField @bind-Value="note" Placeholder="@Localizer["Write a note, mention someone with @"]" Multiline />
        @if (mentionCandidates.Count > 0)
        {
            <BitText Style="color:#757575">@string.Join(", ", mentionCandidates)</BitText>
        }
        <BitButton OnClick="SaveNote">@Localizer["Save note"]</BitButton>
    </BitStack>
</section>

namespace AgentsApp.Client.Core.Components.Pages.Settings;

public partial class QuickNoteSection
{
    [AutoInject] private IUserController userController = default!;
    [AutoInject] private IStorageService storageService = default!;

    private string? note;
    private List<string> mentionCandidates = [];

    protected override async Task OnInitAsync()
    {
        note = await storageService.GetItem("quick-note");
        mentionCandidates = await userController.GetMentionCandidates(CurrentCancellationToken);

        await base.OnInitAsync();
    }

    private async Task SaveNote()
    {
        await storageService.SetItem("quick-note", note);
    }
}

