.feedback-card {
    display: flex;
    flex-direction: column;
    gap: 8px;
    width: 100%;
    max-width: 480px;
    padding: 24px;
    border: 1px solid #dddddd;
    border-radius: 8px;
    background-color: #ffffff;
    color: #222222;
}

.feedback-title {
    margin: 0;
    color: #0b3d91;
}

select,
textarea {
    padding: 8px;
    border: 1px solid #cccccc;
    border-radius: 4px;
    background: #fafafa;
}

.feedback-actions {
    display: flex;
    align-items: center;
    gap: 12px;
}

.feedback-send {
    padding: 8px 20px;
    border: none;
    border-radius: 4px;
    background-color: #0078d4;
    color: #ffffff;
    cursor: pointer;

    &:hover {
        background-color: #005a9e;
    }
}
